CREATE OR REPLACE FUNCTION app_private.special_fee_approve_and_post_v1(p_voucher_id uuid, p_source_kind text DEFAULT 'SPECIAL_PAGE_FEE'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'app_private', 'public'
AS $function$
DECLARE
  v_ie       public.income_expenses;
  v_acc      public.accounts;
  v_posting  uuid;
  v_actor    uuid := auth.uid();
  v_reversed boolean;
  v_mid      uuid;
BEGIN
  SELECT * INTO v_ie FROM public.income_expenses WHERE id = p_voucher_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu %', p_voucher_id USING ERRCODE = 'P0002';
  END IF;
  IF v_ie.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Phiếu % đã huỷ — không ghi sổ', p_voucher_id USING ERRCODE = '55000';
  END IF;

  -- ══ CHỐT LOẠI PHIẾU — hàng rào quan trọng nhất của hàm này ═════════
  -- Hàm này DUYỆT HỘ NGƯỜI DÙNG. Nó tuyệt đối không được chạm vào loại phiếu
  -- mà chủ đã quyết là phải có người duyệt:
  --   • Chủ chốt 31/07: "riêng HOÀN CỌC vẫn chờ duyệt kể cả khi số khớp".
  --   • Phiếu THU (INCOME) không thuộc phạm vi trang đóng phí.
  -- Không có chốt này thì bất kỳ writer nào lỡ gọi nhầm cũng tự duyệt được một
  -- phiếu hoàn cọc — đúng thứ chủ cấm.
  IF v_ie.type IS DISTINCT FROM 'EXPENSE' THEN
    RAISE EXCEPTION
      'Chỉ tự duyệt được phiếu CHI. Phiếu % là loại %.', p_voucher_id, COALESCE(v_ie.type,'(rỗng)')
      USING ERRCODE = '42501';
  END IF;
  IF COALESCE(v_ie.system_source, '') NOT IN ('special_fee.v1', 'fixed_fee', 'utility.bill', 'contract.commission') THEN
    RAISE EXCEPTION
      'Phiếu % không thuộc nhóm phí cố định của trang đóng tiền (nguồn: %) — không tự duyệt.',
      p_voucher_id, COALESCE(v_ie.system_source, '(không rõ)')
      USING ERRCODE = '42501';
  END IF;

  -- ══ (2) REPLAY — phải kiểm bút toán còn SỐNG, không chỉ còn con trỏ ══
  -- Bẫy đã đo được: nếu bút toán cũ ĐÃ BỊ ĐẢO thì trả con trỏ cũ ra rồi đóng
  -- dấu POSTED lên nó = phiếu nói "đã chi" trong khi sổ quỹ nói "chưa" — tiền
  -- biến mất khỏi tồn quỹ mà giao diện vẫn xanh. Phải phân biệt ba trạng thái.
  IF v_ie.active_posting_id_v2 IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.income_expense_postings r
       WHERE r.reversal_of_id = v_ie.active_posting_id_v2 AND r.event_kind = 'REVERSAL'
    ) INTO v_reversed;
    IF v_reversed THEN
      RAISE EXCEPTION
        'Phiếu % đã có bút toán bị ĐẢO — muốn ghi sổ lại phải qua đường ghi sổ lại có kiểm soát, không gọi lại hàm tự duyệt.',
        COALESCE(v_ie.code, p_voucher_id::text)
        USING ERRCODE = '55000';
    END IF;
    RETURN v_ie.active_posting_id_v2;
  END IF;

  -- Bút toán tồn tại theo khoá nguồn nhưng phiếu MẤT con trỏ (a85 xoá con trỏ
  -- khi đảo). Không được ghi đè POSTED lên đó.
  SELECT p.id INTO v_posting
    FROM public.income_expense_postings p
   WHERE p.organization_id = v_ie.organization_id
     AND p.external_source_kind = 'SPECIAL_FEE_VOUCHER'
     AND p.external_source_id   = p_voucher_id
     AND p.event_kind = 'POSTING';
  IF v_posting IS NOT NULL THEN
    RAISE EXCEPTION
      'Phiếu % đã từng được ghi sổ (bút toán %) nhưng con trỏ đã bị gỡ — cần rà tay, không tự ghi lại.',
      COALESCE(v_ie.code, p_voucher_id::text), v_posting
      USING ERRCODE = '55000';
  END IF;

  IF v_ie.account_id IS NULL THEN
    RAISE EXCEPTION 'Phiếu % chưa có sổ quỹ — không tự ghi sổ được', p_voucher_id
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_acc FROM public.accounts WHERE id = v_ie.account_id;
  IF NOT FOUND OR v_acc.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Sổ quỹ của phiếu % không còn hiệu lực', p_voucher_id USING ERRCODE = '22023';
  END IF;
  IF v_acc.organization_id IS DISTINCT FROM v_ie.organization_id THEN
    RAISE EXCEPTION 'Sổ quỹ khác tổ chức của phiếu %', p_voucher_id USING ERRCODE = '42501';
  END IF;

  -- (3) TẮT CẦU a85/a85b cho transaction này. Xem khối chú thích ở trên.
  INSERT INTO app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  VALUES (p_voucher_id, pg_current_xact_id(), 'FINANCE_V2_LIFECYCLE')
  ON CONFLICT (income_expense_id) DO UPDATE
    SET xid = EXCLUDED.xid, purpose = EXCLUDED.purpose, granted_at = now();

  -- (4) Lật APPROVED nếu chưa. Trigger khoá kỳ sẽ tự lên tiếng ở đây.
  IF v_ie.approval_status IS DISTINCT FROM 'APPROVED' THEN
    UPDATE public.income_expenses
       SET approval_status = 'APPROVED',
           review_state    = 'RESOLVED',
           approved_by     = COALESCE(approved_by, v_actor, user_id),
           approved_at     = COALESCE(approved_at, now())
     WHERE id = p_voucher_id;
  END IF;

  -- ══ SỔ ẢO: DUYỆT NHƯNG KHÔNG GHI SỔ QUỸ ═══════════════════════════
  -- Sổ ảo (cấn cọc, cấn trừ) không có tiền ra khỏi két nên không có bút toán
  -- sổ quỹ. Bản nháp trước NÉM LỖI ở đây — sai, vì hôm nay đóng phí từ sổ ảo
  -- vẫn chạy được (cầu a85b tự bỏ qua sổ ảo và phiếu vẫn APPROVED). Ném lỗi là
  -- LẤY MẤT một năng lực đang có. Giữ đúng hành vi cũ: duyệt, không ghi sổ.
  IF COALESCE(v_acc.is_virtual, false) THEN
    UPDATE public.income_expenses
       SET posting_status = COALESCE(NULLIF(posting_status, 'UNPOSTED'), 'NOT_APPLICABLE'),
           updated_at = now()
     WHERE id = p_voucher_id;
    DELETE FROM app_private.ie_transition_authorization
     WHERE income_expense_id = p_voucher_id AND xid = pg_current_xact_id();
    RETURN NULL;
  END IF;

  -- Lõi đòi một membership để ghi "ai ghi sổ", và cột đó NOT NULL. Người tạo
  -- phiếu có thể đã rời tổ chức ⇒ lõi ném 23502 trần không ai hiểu. Chặn sớm
  -- bằng câu tiếng Việt.
  SELECT om.id INTO v_mid
    FROM public.organization_memberships om
   WHERE om.organization_id = v_ie.organization_id
     AND om.user_id = COALESCE(v_ie.approved_by, v_ie.user_id, v_actor)
     AND om.status = 'ACTIVE'
   LIMIT 1;
  IF v_mid IS NULL AND v_ie.maker_membership_id IS NULL THEN
    RAISE EXCEPTION
      'Không xác định được người ghi sổ cho phiếu % (người tạo không còn là thành viên đang hoạt động) — phiếu đã duyệt nhưng cần vào sổ tay.',
      COALESCE(v_ie.code, p_voucher_id::text)
      USING ERRCODE = '22023';
  END IF;

  -- (5) Lõi dùng chung. Khoá replay là chính phiếu này.
  v_posting := app_private.finance_v2_post_voucher_with_source_v1(
    p_org             => v_ie.organization_id,
    p_voucher_id      => p_voucher_id,
    p_source_kind     => p_source_kind,
    p_external_kind   => 'SPECIAL_FEE_VOUCHER',
    p_external_id     => p_voucher_id,
    p_external_line_id=> NULL,
    p_posted_on       => v_ie.voucher_date,
    p_amount_basis    => 'VOUCHER_TOTAL',
    p_generation      => 1
  );

  -- (6) Con trỏ posting. Token còn hiệu lực nên cầu vẫn im (và a85 không khai
  --     posting_status trong danh sách cột kích hoạt nên nó cũng không chạy).
  UPDATE public.income_expenses
     SET active_posting_id_v2 = v_posting,
         posting_id           = v_posting,
         posting_status       = 'POSTED',
         posting_mode         = COALESCE(posting_mode, 'CASHBOOK'),
         posted_at_v2         = now(),
         updated_at           = now()
   WHERE id = p_voucher_id;

  -- (7) TRẢ TOKEN. Mọi writer cùng họ đều dọn; để lại thì cầu a85 CÂM cho toàn
  --     bộ phần còn lại của transaction — một lệnh xoá/đổi tiền sau đó sẽ không
  --     sinh bút toán đảo, tiền kẹt lại trong sổ.
  DELETE FROM app_private.ie_transition_authorization
   WHERE income_expense_id = p_voucher_id AND xid = pg_current_xact_id();

  RETURN v_posting;
END;
$function$

CREATE OR REPLACE FUNCTION app_private.special_fee_rule_check_v1(p_org uuid, p_building uuid, p_kind text, p_period_start date, p_period_end date, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'app_private', 'public'
AS $function$
DECLARE
  v_m        date;
  v_price    numeric;
  v_expected numeric := 0;
  v_months   int := 0;
  v_missing  int := 0;
BEGIN
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN
    RETURN jsonb_build_object('verdict','CONFIG_REQUIRED','reason','Kỳ không hợp lệ');
  END IF;

  -- Giá công bố là mức THEO THÁNG, nên chỉ so được khi kỳ phủ TRỌN các tháng.
  -- Kỳ lẻ (vd 15/06→14/07) không quy ra "mấy tháng" một cách không mập mờ: đếm
  -- theo tháng lịch sẽ ra 2 và đòi gấp đôi tiền cho một kỳ dài 30 ngày.
  -- ⇒ Trả CONFIG_REQUIRED = giữ nguyên hành vi cũ, không tự duyệt, không chặn.
  IF p_period_start <> date_trunc('month', p_period_start)::date
     OR p_period_end <> (date_trunc('month', p_period_end) + interval '1 month - 1 day')::date THEN
    RETURN jsonb_build_object(
      'verdict','CONFIG_REQUIRED',
      'reason','Kỳ không trọn tháng nên không đối chiếu được với giá công bố (giá công bố tính theo tháng)');
  END IF;

  -- Trần vòng lặp: kỳ nhập sai kiểu 1900→2099 sẽ quay 2.400 vòng trong lúc
  -- đang giữ khoá phiếu. 120 tháng (10 năm) là quá đủ cho mọi kỳ phí thật.
  IF (date_trunc('month', p_period_end)::date - date_trunc('month', p_period_start)::date) > 3700 THEN
    RETURN jsonb_build_object(
      'verdict','CONFIG_REQUIRED',
      'reason','Kỳ dài bất thường (trên 10 năm) — không đối chiếu tự động');
  END IF;

  v_m := date_trunc('month', p_period_start)::date;
  WHILE v_m <= date_trunc('month', p_period_end)::date LOOP
    v_months := v_months + 1;
    v_price  := app_private.special_fee_price_for_v1(p_org, p_building, p_kind, v_m);
    IF v_price IS NULL THEN
      v_missing := v_missing + 1;
    ELSE
      v_expected := v_expected + v_price;
    END IF;
    v_m := (v_m + interval '1 month')::date;
  END LOOP;

  IF v_missing > 0 THEN
    RETURN jsonb_build_object(
      'verdict','CONFIG_REQUIRED',
      'months', v_months,
      'missing_months', v_missing,
      'reason','Chưa khai giá ở Cài đặt → Phí cố định cho ' || v_missing || '/' || v_months || ' tháng của kỳ này');
  END IF;

  IF round(COALESCE(p_amount,0), 2) = round(v_expected, 2) THEN
    RETURN jsonb_build_object(
      'verdict','VALID', 'months', v_months, 'expected', round(v_expected,2));
  END IF;

  -- Định dạng số kiểu Việt Nam: dấu CHẤM ngăn nghìn. to_char mặc định theo
  -- lc_numeric của máy chủ (đang là kiểu Anh, cho ra "9,507,910đ") — người Việt
  -- đọc dấu phẩy là dấu thập phân nên câu thông báo sẽ gây hiểu nhầm số tiền.
  RETURN jsonb_build_object(
    'verdict','AMOUNT_MISMATCH',
    'months', v_months,
    'expected', round(v_expected,2),
    'actual',   round(COALESCE(p_amount,0),2),
    'reason', format('Giá đã công bố cho kỳ này là %sđ, số đang chi là %sđ',
                     replace(to_char(round(v_expected), 'FM999G999G999G999'), ',', '.'),
                     replace(to_char(round(COALESCE(p_amount,0)), 'FM999G999G999G999'), ',', '.')));
END;
$function$

CREATE OR REPLACE FUNCTION app_private.utility_ceiling_check_v1(p_org uuid, p_building uuid, p_type text, p_month date, p_amount numeric, p_billed_to_tenants numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'app_private', 'public'
AS $function$
DECLARE v_r record; v_lim numeric;
BEGIN
  SELECT * INTO v_r FROM app_private.utility_ceiling_versions v
   WHERE v.organization_id = p_org AND v.status = 'PUBLISHED'
     AND v.utility_type = p_type
     AND v.effective_from_month <= date_trunc('month', p_month)::date
     AND (v.building_id = p_building OR v.building_id IS NULL)
   ORDER BY (v.building_id IS NOT NULL) DESC, v.effective_from_month DESC
   LIMIT 1;

  IF v_r.id IS NULL THEN
    RETURN jsonb_build_object('verdict','NO_RULE',
      'reason','Chủ chưa công bố trần cho hạng mục này — giữ nguyên hành vi cũ');
  END IF;

  IF v_r.ceiling_amount IS NOT NULL AND round(COALESCE(p_amount,0)) > round(v_r.ceiling_amount) THEN
    RETURN jsonb_build_object('verdict','OVER_CEILING',
      'ceiling', v_r.ceiling_amount, 'actual', p_amount,
      'reason','Số chi ' || replace(to_char(round(COALESCE(p_amount,0)),'FM999G999G999G999'),',','.')
               || 'đ vượt trần ' || replace(to_char(round(v_r.ceiling_amount),'FM999G999G999G999'),',','.') || 'đ');
  END IF;

  IF v_r.max_ratio_to_billed IS NOT NULL AND COALESCE(p_billed_to_tenants,0) > 0 THEN
    v_lim := round(p_billed_to_tenants * v_r.max_ratio_to_billed);
    IF round(COALESCE(p_amount,0)) > v_lim THEN
      RETURN jsonb_build_object('verdict','OVER_RATIO',
        'limit', v_lim, 'billed', p_billed_to_tenants, 'ratio', v_r.max_ratio_to_billed,
        'reason','Số chi vượt ' || v_r.max_ratio_to_billed || ' lần tiền đã thu của khách ('
                 || replace(to_char(round(p_billed_to_tenants),'FM999G999G999G999'),',','.') || 'đ)');
    END IF;
  END IF;

  -- Mẫu số 0 mà vẫn chi ⇒ đáng ngờ, nhưng không chặn: có toà chưa kịp chốt số khách.
  IF v_r.max_ratio_to_billed IS NOT NULL AND COALESCE(p_billed_to_tenants,0) = 0
     AND COALESCE(p_amount,0) > 0 THEN
    RETURN jsonb_build_object('verdict','WARN_NO_BILLED',
      'reason','Chưa thu đồng nào của khách cho kỳ này mà đã chi nhà cung cấp — nên rà lại');
  END IF;

  RETURN jsonb_build_object('verdict','WITHIN_LIMIT');
END;
$function$

CREATE OR REPLACE FUNCTION public.set_special_fee_price_v1(p_building_id uuid, p_fee_category text, p_amount numeric, p_effective_from_month text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org   uuid;
  v_month date;
  v_id    uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_fee_category NOT IN ('tien_nha','dien','nuoc','internet','quan_ly',
                            've_sinh','cong_an','rac','thang_may') THEN
    RAISE EXCEPTION 'Hạng mục phí không hợp lệ: %', p_fee_category USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Giá công bố phải lớn hơn 0' USING ERRCODE = '22023';
  END IF;

  SELECT b.organization_id INTO v_org FROM public.buildings b
   WHERE b.id = p_building_id AND b.deleted_at IS NULL;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor)) THEN
    RAISE EXCEPTION
      'Chỉ chủ tổ chức mới công bố được giá phí cố định. Giá này quyết định phiếu nào được tự duyệt, nên không mở cho người khác.'
      USING ERRCODE = '42501';
  END IF;

  IF p_effective_from_month IS NULL THEN
    v_month := date_trunc('month', public.org_today_v1(v_org))::date;
  ELSE
    IF p_effective_from_month !~ '^\d{4}-\d{2}$' THEN
      RAISE EXCEPTION 'Tháng hiệu lực phải dạng YYYY-MM' USING ERRCODE = '22023';
    END IF;
    v_month := to_date(p_effective_from_month || '-01', 'YYYY-MM-DD');
  END IF;

  -- Công bố lại cho CÙNG tháng hiệu lực: cho bản cũ nghỉ, không xoá.
  UPDATE app_private.special_fee_price_versions
     SET status = 'RETIRED', retired_at = now()
   WHERE organization_id = v_org AND building_id = p_building_id
     AND fee_category = p_fee_category AND effective_from_month = v_month
     AND status = 'PUBLISHED';

  INSERT INTO app_private.special_fee_price_versions
    (organization_id, building_id, fee_category, effective_from_month,
     amount, source, note, created_by)
  VALUES (v_org, p_building_id, p_fee_category, v_month,
          round(p_amount, 2), 'OWNER', NULLIF(btrim(COALESCE(p_note,'')), ''), v_actor)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'id', v_id, 'buildingId', p_building_id, 'feeCategory', p_fee_category,
    'amount', round(p_amount, 2), 'effectiveFrom', to_char(v_month, 'YYYY-MM'),
    'note', 'Giá áp dụng từ tháng ' || to_char(v_month, 'MM/YYYY') || '. Phiếu các tháng trước giữ nguyên giá cũ.');
END;
$function$

CREATE OR REPLACE FUNCTION public.set_utility_ceiling_v1(p_utility_type text, p_ceiling_amount numeric DEFAULT NULL::numeric, p_max_ratio_to_billed numeric DEFAULT NULL::numeric, p_building_id uuid DEFAULT NULL::uuid, p_effective_from_month text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_org uuid; v_month date; v_id uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE='42501'; END IF;
  IF p_utility_type NOT IN ('ELECTRIC','WATER') THEN
    RAISE EXCEPTION 'Loại chỉ nhận ELECTRIC hoặc WATER' USING ERRCODE='22023';
  END IF;
  IF p_ceiling_amount IS NULL AND p_max_ratio_to_billed IS NULL THEN
    RAISE EXCEPTION 'Phải đặt ít nhất một trong hai: trần tiền, hoặc tỉ lệ so với tiền đã thu'
      USING ERRCODE='22023';
  END IF;

  IF p_building_id IS NOT NULL THEN
    SELECT b.organization_id INTO v_org FROM public.buildings b
     WHERE b.id = p_building_id AND b.deleted_at IS NULL;
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không tìm thấy toà nhà' USING ERRCODE='P0002'; END IF;
  ELSE
    v_org := COALESCE(p_organization_id,
      (SELECT m.organization_id FROM public.organization_memberships m
        WHERE m.user_id = v_actor AND m.status='ACTIVE' LIMIT 1));
    IF v_org IS NULL THEN RAISE EXCEPTION 'Không xác định được tổ chức' USING ERRCODE='22023'; END IF;
  END IF;

  IF NOT (public.is_super_admin() OR app_private.is_org_owner_v1(v_org, v_actor)) THEN
    RAISE EXCEPTION 'Chỉ chủ tổ chức mới đặt được trần chi' USING ERRCODE='42501';
  END IF;

  v_month := CASE WHEN p_effective_from_month IS NULL
    THEN date_trunc('month', public.org_today_v1(v_org))::date
    ELSE to_date(p_effective_from_month || '-01','YYYY-MM-DD') END;

  UPDATE app_private.utility_ceiling_versions
     SET status='RETIRED', retired_at=now()
   WHERE organization_id=v_org AND utility_type=p_utility_type
     AND COALESCE(building_id,'00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(p_building_id,'00000000-0000-0000-0000-000000000000'::uuid)
     AND effective_from_month=v_month AND status='PUBLISHED';

  INSERT INTO app_private.utility_ceiling_versions
    (organization_id, building_id, utility_type, effective_from_month,
     ceiling_amount, max_ratio_to_billed, note, created_by)
  VALUES (v_org, p_building_id, p_utility_type, v_month,
          p_ceiling_amount, p_max_ratio_to_billed,
          NULLIF(btrim(COALESCE(p_note,'')),''), v_actor)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id, 'utilityType', p_utility_type,
    'ceilingAmount', p_ceiling_amount, 'maxRatio', p_max_ratio_to_billed,
    'effectiveFrom', to_char(v_month,'YYYY-MM'),
    'note','Vượt trần thì phiếu vẫn tạo được nhưng nằm chờ duyệt kèm lý do.');
END;
$function$
